 @TableId(type=IdType.AUTO) private Long id; private Long userId; private String title; private String content; private Integer layout; private Long channelId; private String labels; private String coverImages; private WmNewsStatus status; private LocalDateTime submittedTime; private LocalDateTime publishTime; private String reason; private Long articleId;private Long auditVersion;private String auditSource;
 public Long getId(){return id;} public void setId(Long v){id=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public Integer getLayout(){return layout;} public void setLayout(Integer v){layout=v;} public Long getChannelId(){return channelId;} public void setChannelId(Long v){channelId=v;} public String getLabels(){return labels;} public void setLabels(String v){labels=v;} public String getCoverImages(){return coverImages;} public void setCoverImages(String v){coverImages=v;} public WmNewsStatus getStatus(){return status;} public void setStatus(WmNewsStatus v){status=v;} public LocalDateTime getSubmittedTime(){return submittedTime;} public void setSubmittedTime(LocalDateTime v){submittedTime=v;} public LocalDateTime getPublishTime(){return publishTime;} public void setPublishTime(LocalDateTime v){publishTime=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public Long getArticleId(){return articleId;} public void setArticleId(Long v){articleId=v;}public Long getAuditVersion(){return auditVersion;}public void setAuditVersion(Long v){auditVersion=v;}public String getAuditSource(){return auditSource;}public void setAuditSource(String v){auditSource=v;}
